"""ING Romania layout on samples/ing-2026-09.pdf (synthetic; generated by samples/tools/generate_ing_sample.py)."""

from __future__ import annotations

import io
import json
from dataclasses import replace
from decimal import Decimal

import pdfplumber
import pytest

from spendly_pdf_parser.extraction import ExtractionError, extract_statement
from spendly_pdf_parser.extraction import text_table as tt
from spendly_pdf_parser.extraction.ing import IngStatementLayout, _Pending
from spendly_pdf_parser.pipeline import StatementContext, build_from_raw, parse_pdf

from .conftest import ACCOUNT_ID, REPO_DIR, SAMPLE_PDF, STATEMENT_ID
from .helpers import assert_no_pii, minimal_pdf

ING_PDF = REPO_DIR / "samples" / "ing-2026-09.pdf"
CTX = StatementContext(STATEMENT_ID, ACCOUNT_ID, "RON", "upl-ing-test")
LAYOUTS = [IngStatementLayout()]
# Header data and balances of the sample that must never leave the parser.
ING_FORBIDDEN = ("Exemplului", "4111 1111 1111 1111", "4111111111111111", "411111******1111",
                 "RO54 SPND 0000 1111 2222 3333", "RO54SPND0000111122223333", "Titular",
                 "4.000,00", "4000.00", "5.295,41", "5295.41")


@pytest.fixture(scope="module")
def ing_bytes() -> bytes:
    return ING_PDF.read_bytes()


@pytest.fixture(scope="module")
def outcome(ing_bytes, sanitizer, contracts):
    return parse_pdf(ing_bytes, CTX, sanitizer, contracts, LAYOUTS)


def _detect(data: bytes) -> bool:
    with pdfplumber.open(io.BytesIO(data)) as pdf:
        return IngStatementLayout().detect(pdf)


def test_detects_only_ing(ing_bytes) -> None:
    assert _detect(ing_bytes) is True
    assert _detect(SAMPLE_PDF.read_bytes()) is False
    assert _detect(minimal_pdf("ING Bank Extras de cont, but no table")) is False


def test_extracts_rows_period_currency_and_balances(ing_bytes) -> None:
    raw = extract_statement(ing_bytes, LAYOUTS)
    assert raw.layout == "ing-ro"
    assert len(raw.rows) == 12
    assert raw.currency == "RON"
    assert (raw.period_start.isoformat(), raw.period_end.isoformat()) == ("2026-09-01", "2026-09-30")
    assert raw.opening_balance == Decimal("4000.00") and raw.closing_balance == Decimal("5295.41")
    assert [r.booking_date for r in raw.rows][:3] == ["2026-09-01", "2026-09-02", "2026-09-03"]
    assert raw.rows[1].debit == "187.45" and raw.rows[1].credit == ""
    assert raw.rows[0].credit == "6500.00" and raw.rows[0].debit == ""


def test_pending_section_is_skipped(ing_bytes) -> None:
    raw = extract_statement(ing_bytes, LAYOUTS)
    assert all("TAXI" not in r.description for r in raw.rows)
    assert all(r.debit != "45.00" for r in raw.rows)


def test_descriptions_keep_merchant_and_counterparty_drop_noise(ing_bytes) -> None:
    raw = extract_statement(ing_bytes, LAYOUTS)
    pos = raw.rows[1].description
    assert pos == "Cumparare POS LIDL 1234 IASI RO"
    transfer = raw.rows[2].description
    assert transfer.startswith("Transfer Beneficiar: Ion Popescu In contul: ")
    assert "Detalii: chirie septembrie" in transfer
    for r in raw.rows:
        for noise in ("Numar card", "Numar autorizare", "Data autorizarii", "Referinta", "Banca", "411111"):
            assert noise not in r.description


def test_pipeline_imports_balanced_statement(outcome, contracts) -> None:
    assert outcome.event_type == "TransactionsImported"
    assert contracts.validate(outcome.event) == []
    s = outcome.summary
    assert s.balanced is True and s.layout == "ing-ro"
    assert (s.transaction_count, s.debit_count, s.credit_count) == (12, 10, 2)
    assert (s.debit_total, s.credit_total) == ("5354.59", "6650.00")
    payload = outcome.event["payload"]
    assert (payload["periodStart"], payload["periodEnd"]) == ("2026-09-01", "2026-09-30")


def test_counterparties_are_tokenized(outcome) -> None:
    tx = outcome.event["payload"]["transactions"]
    transfer = tx[2]
    assert transfer["counterpartyTokenKind"] == "IBAN" and len(transfer["counterpartyToken"]) == 64
    assert "RO**…0000" in transfer["description"] and "[PERSON#" in transfer["description"]
    assert tx[1]["counterpartyToken"] is None  # card purchase: no counterparty account


def test_no_header_data_or_balances_leak(outcome) -> None:
    dumped = json.dumps(outcome.event, ensure_ascii=False) + json.dumps(outcome.summary.as_dict())
    assert_no_pii(dumped)
    for needle in ING_FORBIDDEN:
        assert needle not in dumped, f"forbidden value leaked: {needle[:6]}..."


def test_tampered_row_gives_balance_mismatch(ing_bytes, sanitizer, contracts) -> None:
    raw = extract_statement(ing_bytes, LAYOUTS)
    rows = list(raw.rows)
    rows[1] = replace(rows[1], debit="188.45")
    out = build_from_raw(replace(raw, rows=rows), CTX, sanitizer, contracts)
    assert out.reason == "BALANCE_MISMATCH"


def test_without_table_header_is_unsupported() -> None:
    with pytest.raises(ExtractionError) as err:
        IngStatementLayout._read_rows([])
    assert err.value.reason == "UNSUPPORTED_LAYOUT"


def test_unlabelled_line_continues_only_a_kept_label() -> None:
    pending = _Pending(tt.TableRow(0, "01 septembrie 2026", "Transfer", debit=Decimal("1.00")))
    IngStatementLayout._detail(pending, "Detalii: plata pentru")
    IngStatementLayout._detail(pending, "servicii septembrie")
    IngStatementLayout._detail(pending, "Referinta: ABC123")
    IngStatementLayout._detail(pending, "XYZ987")
    IngStatementLayout._detail(pending, "Terminal:")
    assert pending.finish().description == "Transfer Detalii: plata pentru servicii septembrie"
